// Replace with your own addresses, in lower case. Never commit real addresses to the repo.
const TEST_ADDRESSES = ['replace-with-your-test-address@example.com'];
const OWNER_ADDRESS = 'replace-with-the-owner-test-address@example.com';
const SITE = 'https://ido0308-blip.github.io/wizeroll/';
const FOOTER = 'WIZEROLL demo. This email was sent to a test address.';

const VERDICT_LABELS = {
  fit: 'it fits',
  fit_with_reservation: 'it fits, with a reservation',
};

// Rows come from the query: fit checks with a positive verdict, no order and no reminder, older than 3 days.
// Checked again here, so a wrong filter in the query never sends a reminder twice.
return $input.all()
  .map((item) => item.json)
  .filter((row) => row.id
    && row.request_type === 'fit_check'
    && row.wants_order === false
    && row.reminder_sent === false
    && VERDICT_LABELS[row.verdict]
    && TEST_ADDRESSES.includes(String(row.customer_email ?? '').trim().toLowerCase()))
  .map((row) => ({
    json: {
      request_id: row.id,
      to: String(row.customer_email).trim().toLowerCase(),
      subject: 'Still thinking about the WIZEROLL stool?',
      text: [
        'Hi,', '',
        `A few days ago you checked whether the WIZEROLL stool fits your workstation, and the answer was: ${VERDICT_LABELS[row.verdict]}.`, '',
        'If you still want it, you can come back to the product page:',
        SITE, '',
        'This is a one-time reminder.', '',
        FOOTER,
      ].join('\n'),
    },
  }));

// Replace with your own addresses, in lower case. Never commit real addresses to the repo.
const TEST_ADDRESSES = ['replace-with-your-test-address@example.com'];
const OWNER_ADDRESS = 'replace-with-the-owner-test-address@example.com';
const SITE = 'https://ido0308-blip.github.io/wizeroll/';
const FOOTER = 'WIZEROLL demo. This email was sent to a test address.';

// Rows come from the query: service requests still pending, no alert yet, older than 2 days.
return $input.all()
  .map((item) => item.json)
  .filter((row) => row.id
    && row.request_type === 'service'
    && row.status === 'pending'
    && row.escalation_sent === false)
  .map((row) => {
    const log = Array.isArray(row.conversation_log) ? row.conversation_log : [];
    const firstMessage = log.find((entry) => entry.role === 'customer')?.text ?? '';
    return {
      json: {
        request_id: row.id,
        to: OWNER_ADDRESS,
        subject: 'WIZEROLL: a service request is waiting for more than 2 days',
        text: [
          'A service request has been waiting for your decision for more than two days.', '',
          `Customer: ${row.customer_email}`,
          `Opened: ${String(row.created_at ?? '').slice(0, 10)}`,
          `First message: ${firstMessage}`, '',
          'Open the dashboard to approve or reject it:',
          `${SITE}dashboard.html`, '',
          FOOTER,
        ].join('\n'),
      },
    };
  });
